namespace Prism.Help;

/// <summary>
/// Help written for one ribbon button, keyed "icon|Label" (or "Tab:icon|Label" when the same icon and
/// label mean different tools on different tabs). These cover buttons whose icon is shared with an
/// unrelated tool, so the icon's own topic would describe the wrong thing.
/// </summary>
public static partial class ToolHelp
{
    static ToolHelpTopic? FindButton(string? key) => key switch
    {
        // ---- datum ----
        "move|Gizmo" => Words(key, "Gizmo", "Show the gizmo and place it: it is the frame that sketches, datums and moves work from.",
            "1. Choose Gizmo.\n2. Drag its arrows, rings or center to position it.\n3. Set binding, handles and snapping in the panel.",
            "Placing the gizmo changes no geometry; Move uses the same handles to move objects."),
        "origin-plane|Construction Plane" => T(key, "Construction Plane", "Make reference planes: offset (one or a whole stack), angled, midway, square to a curve or through three points.",
            "Start: a body", "Result: a stack of offset planes",
            "1. Choose Construction Plane.\n2. Pick the method and the face, plane or curve it starts from.\n3. Set the distance or angle (and count for a stack), then accept.",
            "Sketch on the planes or use them as mirror, split and section references.", "construction-plane"),

        // ---- curves ----
        "move|Transform" => Words(key, "Transform", "Move, rotate or scale the points and curves you selected in a sketch, with the gizmo or by typing exact values.",
            "1. Select points or curves.\n2. Choose Transform: the gizmo sits on the selection and its panel opens.\n3. Drag the arrows or rings, press R to rotate or S to scale, or type location, rotation and scale.",
            "Scale works per axis, so two points can be squashed together along one gizmo axis. No bind step is needed."),
        "origin-point|Insert Point" => Words(key, "Insert Point", "Add a point to a curve you already drew in a sketch: a line becomes two lines, an arc or circle two arcs, and a spline gains a point.",
            "1. In a sketch, choose Insert Point.\n2. Click a line, arc, circle or spline where the point should go.\n3. Click more curves, or press Esc to finish.",
            "A circle splits at the clicked point and the point opposite it. The two halves of a split line stay one straight line."),
        "section|Intersection Curve" => T(key, "Intersection Curve", "Make the curve where two planes, faces, surfaces or bodies cross, or the 3D curve shared by two flat curves on different planes.",
            "Start: a cylinder crossed by a plane", "Result: the curve where they meet",
            "1. Choose Intersection Curve.\n2. Pick the first and second object.\n3. Accept to keep the curve.",
            "The curve is ordinary geometry: sweep along it, loft through it or trim with it.", "intersection-curve"),
        "section|Project" => T(key, "Project Curve", "Drop curves onto a surface, straight along a direction or by pulling to the nearest point.",
            "Start: a curve above a body", "Result: the curve lying on the face",
            "1. Choose Project.\n2. Pick the curves, then the surface or body.\n3. Choose straight or nearest-point, then accept.",
            "Projected curves can trim the surface or guide an emboss.", "project-curve"),
        "curve-through|Draw on Surface" => Words(key, "Draw on Surface", "Draw a curve directly on a surface the way the spline tool draws one: click a few points and a smooth curve passes through them, over the edge onto the next face if need be.",
            "1. Choose Draw on Surface.\n2. Click points on a face, surface, freeform form, NURBS surface or mesh.\n3. Drag a point to move it, press Delete to remove the selected one, and press Enter or double-click to finish.",
            "Fewer points make a calmer curve. A spot that cannot be reached without crossing empty space is refused. The curve stays where it was drawn if the body changes later."),
        "curve-through|Isocurves" => T(key, "Isocurves", "Pull curves of constant U or V out of a surface.",
            "Start: a surface", "Result: curves following its grid",
            "1. Choose Isocurves.\n2. Pick the surface.\n3. Choose the direction and count, then accept.",
            "Isocurves show how a surface flows and make good loft or sweep guides.", "isocurves"),
        "section|Contour" => T(key, "Contour", "Slice a body into evenly spaced section curves.",
            "Start: a body", "Result: evenly spaced slices",
            "1. Choose Contour.\n2. Pick the body.\n3. Set the slicing direction and spacing, then accept.",
            "Contours are handy for checking a shape's flow or for laser-cut layer models.", "contour"),
        "curve-through|Duplicate Edge" => T(key, "Duplicate Edge", "Copy the edges you click as separate curves.",
            "Start: pick an edge", "Result: a curve copied from it",
            "1. Choose Duplicate Edge.\n2. Click the edges to copy.\n3. Accept; the curves stay where the edges are.",
            "The copy is independent of the body: use it as a sweep path or a sketch reference.", "duplicate-edge"),
        "offset|Offset Curve" => T(key, "Offset Curve", "Copy a flat curve parallel to itself at a set distance.",
            "Start: a curve", "Result: a parallel copy",
            "1. Choose Offset Curve.\n2. Pick the curve.\n3. Set the distance and side, then accept.",
            "Offsetting a closed outline grows or shrinks the whole outline.", "offset-curve"),
        "curve-through|Blend Curve" => T(key, "Blend Curve", "Join two curves with a new curve that keeps their position, direction or bend.",
            "Start: two separate curves", "Result: a smooth bridge between them",
            "1. Choose Blend Curve.\n2. Pick the end of each curve.\n3. Choose how smoothly it joins, then accept.",
            "Matching the bend as well as the direction gives the smoothest joint.", "blend-curve"),
        "knit|Join" => T(key, "Join Curves", "Join curves that touch end to end into one curve.",
            "Start: separate touching segments", "Result: one continuous curve",
            "1. Choose Join.\n2. Pick the curves.\n3. Accept to join them.",
            "Joined curves can be swept along or extruded as one profile.", "join-curves"),
        "unstitch|Explode" => T(key, "Explode Curve", "Break a curve or sketch into its separate segments.",
            "Start: one closed curve", "Result: its separate segments",
            "1. Choose Explode.\n2. Pick the curve or sketch.\n3. Accept; each segment becomes its own curve.",
            "Join puts the pieces back together.", "explode-curve"),
        "trim|Trim Curve" => T(key, "Trim Curve", "Keep part of a curve, or cut it into pieces where other curves cross it.",
            "Start: a curve crossing another", "Result: the curve cut back",
            "1. Choose Trim Curve.\n2. Pick the curve and the cutting curve or point.\n3. Choose which part to keep, then accept.",
            "Split instead of trim to keep every piece.", "trim-curve"),
        "extend-surface|Extend Curve" => T(key, "Extend Curve", "Grow a curve past its end, keeping it smooth.",
            "Start: a short arc", "Result: the arc continued",
            "1. Choose Extend Curve.\n2. Pick near the end to extend.\n3. Set the length, then accept.",
            "The extension continues the curve's direction and bend.", "extend-curve"),
        "raise-degree|Rebuild Curve" => T(key, "Rebuild Curve", "Redraw a curve with a chosen number of points.",
            "Start: a lumpy curve with many points", "Result: a smooth curve with few points",
            "1. Choose Rebuild Curve.\n2. Pick the curve.\n3. Set the point count and degree, check the deviation, then accept.",
            "Fewer points make a smoother, fairer curve; more points follow the original closer.", "rebuild-curve"),

        // ---- solid ----
        "splitbody|Split Face" => T(key, "Split Face", "Divide a face along a plane, edge or sketch; the shape stays the same.",
            "Start: a whole face", "Result: the face in two parts",
            "1. Choose Split Face.\n2. Pick the face, then the plane, edge or sketch to split along.\n3. Accept.",
            "Split faces let you draft, color or load just part of a face.", "split-face"),
        "pushpull|Extend / Trim Face" => T(key, "Extend / Trim Face", "Grow or shrink flat faces until they meet a target plane or face.",
            "Start: a face and a target plane", "Result: the face moved to the target",
            "1. Choose Extend / Trim Face.\n2. Pick the faces to move.\n3. Pick the target plane or face, then accept.",
            "Use it to make imported parts line up exactly.", "extend-face"),
        "replaceface|Replace Face" => T(key, "Replace Face", "Make faces lie on another plane or face.",
            "Start: a face and a sloped target", "Result: the face on the target",
            "1. Choose Replace Face.\n2. Pick the faces to replace.\n3. Pick the target plane or face, then accept.",
            "The neighbouring faces stretch to stay connected.", "replace-face"),
        "replaceface|Match Face" => T(key, "Match Face", "Give faces the plane, cylinder radius or cone angle of a source face.",
            "Start: two different cylinders", "Result: both the same radius",
            "1. Choose Match Face.\n2. Pick the faces to change.\n3. Pick the source face, then accept.",
            "Handy for making imported bosses or holes match each other.", "match-face"),
        "replaceface|Merge Faces" => T(key, "Merge Faces", "Join neighbouring faces on the same surface into one face.",
            "Start: a face split by a seam", "Result: one clean face",
            "1. Choose Merge Faces.\n2. Pick the faces to join.\n3. Accept.",
            "Merging removes edges left over from imports and booleans.", "merge-faces"),
        "pattern-linear|Edit Pattern" => T(key, "Edit Pattern", "Change the spacing or count of a line, grid or circle of features, or drop one.",
            "Start: four holes in a row", "Result: three holes, wider apart",
            "1. Choose Edit Pattern.\n2. Click one feature of the pattern.\n3. Change the count or spacing, or drop a copy, then accept.",
            "Works on imported parts: the pattern is found from the geometry.", "edit-pattern"),
        "patch|Fill / Cap" => T(key, "Fill / Cap", "Cap an open loop of edges with a flat face or smooth patch so the body closes.",
            "Start: a body with an open top", "Result: the opening capped",
            "1. Choose Fill / Cap.\n2. Pick the open edge loop.\n3. Choose flat or smooth, then accept.",
            "Use it after deleting faces or to close an imported shell.", "fill-cap"),
        "finish|Finish Editing" => Words(key, "Finish Editing", "Leave Direct Edit and go back to where you were.",
            "Choose Finish Editing when your direct edits are done; they stay in the model.", ""),

        // ---- surface ----
        "unstitch|Unsew" => T(key, "Unsew", "Take a sewn shell, or just some of its faces, apart into separate surfaces.",
            "Start: one closed body", "Result: separate surfaces",
            "1. Choose Unsew.\n2. Pick the shell, or the faces to take off.\n3. Accept.",
            "Sew joins them again; a closed result becomes a solid.", "unsew"),
        "reverse-normal|Reverse Normal" => Words(key, "Reverse Normal", "Turn a surface around so its other side faces out.",
            "1. Choose Reverse Normal.\n2. Pick the surfaces.\n3. Accept; shading and offset directions flip.",
            "Fix surfaces that shade dark or offset the wrong way."),
        "surface-trim" => T(key, "Trim Surface", "Cut a surface with a plane, another surface or a solid and keep the side you want.",
            "Start: a surface and a cutting plane", "Result: the side you kept",
            "1. Choose Trim.\n2. Pick the surface, then the plane, surface or solid that cuts it.\n3. Pick the side to keep, then accept.",
            "Untrim brings the cut-away part back.", "surface-trim"),
        "surface-offset" => T(key, "Offset Surface", "Create a parallel copy of a surface or face.",
            "Start: a surface", "Result: a parallel copy",
            "1. Choose Offset.\n2. Pick the surface or face.\n3. Set the distance and side, then accept.",
            "Thicken makes a solid between a surface and its offset in one step.", "surface-offset"),
        "curve-comb" => T(key, "Curvature Graph", "Show a comb of hairs along a curve to judge how smooth it is.",
            "Start: a curve", "Result: its curvature comb",
            "1. Choose Curvature Graph.\n2. Pick the curve.\n3. Read the comb; clear it when done.",
            "An even, flowing comb means a fair curve; a sudden jump shows a kink.", "curve-comb"),
        "nurbs-patch|Match Surface" => T(key, "Match Surface", "Match compatible natural patch boundaries with G0, G1 or G2 continuity.",
            "Start: two patches meeting at a kink", "Result: a smooth joint",
            "1. Choose Match Surface.\n2. Pick the boundary to change, then the one to match.\n3. Choose G0, G1 or G2, then accept.",
            "Check Seam reports how well two boundaries meet.", "match-surface"),
        "form-sweep|Pipe" => T(key, "Freeform Pipe", "Make a round, taperable tube form along a path (limbs, tails, stems).",
            "Start: a path curve", "Result: a tube form along it",
            "1. Choose Pipe.\n2. Pick the path curve.\n3. Set the radius and taper, then accept.",
            "The tube stays a freeform cage you can keep sculpting.", "pipe"),
        "clear-analysis|Clear Colors" => Words(key, "Clear Colors", "Remove analysis colors from meshes.", "Choose Clear Colors; the meshes return to normal shading.", ""),
        "clear-analysis|Clear Compare" => Words(key, "Clear Compare", "Empty the material comparison table.", "Choose Clear Compare, then add materials to compare again.", ""),
        "animation|Edit / Play" => Find("animation"),
        "sweep-surface|Pipe" => T(key, "Pipe", "Make a round, optionally tapered tube along a path curve.",
            "Start: a path curve", "Result: a tube along it",
            "1. Choose Pipe.\n2. Pick the path curve.\n3. Set the radius (and end radius for a taper); choose solid or surface, then accept.",
            "Pipe needs only the path; Sweep needs a profile too.", "pipe"),
        "curvature|Check Seam" => Words(key, "Check Seam", "Inspect how smoothly two natural patch boundaries meet, from sampled position, tangent and curvature.",
            "1. Choose Check Seam.\n2. Pick the two patch boundaries.\n3. Read the gap, angle and curvature differences.",
            "Use Match Surface to fix a seam that is not smooth enough."),
        "Sketch:curvature|Curvature" => T(key, "Curvature Comb", "Show hairs along splines, ellipses and arcs that show how sharply they bend.",
            "Start: a curve", "Result: its curvature comb",
            "1. Turn on Curvature.\n2. Edit the curve and watch the comb.\n3. Turn it off when done.",
            "An even, flowing comb means a fair curve; a sudden jump shows a kink.", "curve-comb"),

        // ---- freeform ----
        "form-plane|Plane" => T(key, "Freeform Plane", "Start a form from a flat grid of faces to push, pull and sculpt.", "A point", "A flat grid of faces",
            FormSteps, "Use a plane for panels, wings and other thin shapes.", "form-plane"),
        "form-box|Box" => T(key, "Freeform Box", "Start a form from a box cage that smooths into a rounded block.", "A point", "A box cage",
            FormSteps, "Most freeform shapes start as a box: pull its faces out into limbs and handles.", "form-box"),
        "form-sphere|Sphere" => T(key, "Freeform Sphere", "Start a form from a quad-ball: a sphere made of evenly sized four-sided faces.", "A point", "A quad-ball cage",
