        "form-torus|Torus" => T(key, "Freeform Torus", "Start a form from a ring-shaped cage.", "A point", "A ring",
            FormSteps, "Good for handles, grips and rings.", "form-torus"),
        "form-face|Fill holes" => T(key, "Fill Holes", "Cap open borders of the form with faces.", "Start: a form with an open side", "Result: the opening capped",
            "1. Select the open border edges, or nothing for every hole.\n2. Choose Fill holes.",
            "Closed forms convert to solids; open ones convert to surfaces.", "form-fill"),
        "form-face|Flatten" => T(key, "Flatten Points", "Press the selected points onto a plane.", "Start: a bumpy face", "Result: the points pressed flat",
            "1. Select the points or faces to flatten.\n2. Choose Flatten.\n3. Adjust the plane in the panel if needed.",
            "Flatten the base of a form so it sits on a table.", "form-flatten"),
        "form-face|Inset" => T(key, "Inset", "Shrink the selected faces into smaller faces with a ring of new faces around them.", "Start: a face", "Result: a smaller face with a ring around it",
            "1. Select faces.\n2. Choose Inset.\n3. Set the amount, depth and 'each face on its own' in the panel.",
            "Inset then Extrude makes buttons, vents and recesses.", "form-inset"),
        "form-box|Thicken" => T(key, "Thicken Form", "Give the cage wall thickness.", "Start: a thin sheet", "Result: a sheet with thickness",
            "1. Select the form.\n2. Choose Thicken.\n3. Set the width in the panel.",
            "Thicken open forms before converting them to a solid.", "form-thicken"),
        "form-extrude|Extrude" => T(key, "Extrude Faces", "Extrude the selected faces (or open edges) out of the form.", "Start: select a face", "Result: the face pulled out",
            "1. Select faces or open edges.\n2. Choose Extrude.\n3. Drag the arrows or type the distance.",
            "Extrude faces one ring at a time to build limbs with control.", "form-extrude-faces"),
        "form-edit|Edit Freeform" => T(key, "Edit Freeform", "Select vertices, edges or faces of the cage and move them with the manipulator.", "Start: a cage", "Result: the cage reshaped",
            "1. Choose Edit Freeform.\n2. Select points, edges or faces.\n3. Drag the manipulator to move, turn or scale them.",
            "Move a few cage points at a time: the smooth surface follows.", "edit-points"),
        "form-edit|Check Quality" => T(key, "Check Quality", "Mark poles, triangles and n-gons, see how stretched the quads are and how the curvature varies, or color the surface by its distance to a reference.", "Start: a form", "Result: colored by curvature",
            "1. Choose Check Quality.\n2. Pick what to show in the panel.\n3. Fix flagged areas, then turn it off.",
            "Even curvature colors mean a smooth, well-spread cage.", "form-quality"),
        "form-loop|Slide" => T(key, "Slide Edge Loop", "Move the selected edge loop along its neighbouring edges without changing the shape much.", "Start: an edge loop", "Result: the loop slid along",
            "1. Select an edge loop.\n2. Choose Slide.\n3. Set the amount in the panel.",
            "Slide loops toward a corner to make the smooth surface sharper there.", "edge-loop-slide"),
        "form-loop|Insert Edge" => T(key, "Insert Edge", "Click an edge to add an edge loop across it.", "Start: a coarse cage", "Result: a new loop across it",
            "1. Choose Insert Edge.\n2. Click edges to add loops; the tool stays on until Esc.\n3. Set count and position in the panel.",
            "Add loops where you need more control, not everywhere.", "edge-loop-insert"),
        "form-loop|Select Loop" => T(key, "Select Loop", "Select a whole edge loop or edge ring from the selected edge.", "Start: one edge", "Result: the whole ring selected",
            "1. Select one edge.\n2. Choose Select Loop.\n3. Pick Loop (end to end) or Ring (across quads) under Edge selection.",
            "Alt+L and Alt+R pick a loop or ring directly.", "edge-loop-select"),
        "form-subdivide|Split face" => T(key, "Split Face", "Cut a face in two between two selected corners.", "Start: a face", "Result: the face in two",
