        "form-flip|Smooth" => T(key, "Smooth Points", "Relax the selected points toward their neighbours.", "Start: a lumpy cage", "Result: the points evened out",
            "1. Select points, or nothing for all.\n2. Choose Smooth.\n3. Repeat for more smoothing.",
            "Smoothing evens out spacing as well as bumps.", "form-smooth-points"),
        "form-flip|Smooth surface" => T(key, "Smooth Surface", "Switch between the smoothed surface and the plain cage faces.", "Start: the plain cage", "Result: the smooth surface",
            "1. Choose Smooth surface to toggle the view.\n2. Set the levels under Smoothness in the panel.",
            "Edit with the cage visible and check the result smoothed.", "form-smooth-surface"),
        "form-flip|Pull" => T(key, "Pull to Surface", "Pull the selected points (or all) onto the smooth surface the cage produces.", "Start: a cage off its surface", "Result: points on the surface",
            "1. Select points, or nothing for all.\n2. Choose Pull.",
            "Pulling makes the cage points sit exactly on the shape you see.", "form-smooth-points"),
        "form-flip|Flip normals" => Words(key, "Flip Normals", "Reverse which side of the form is the outside.",
